<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import PhoneModelMultiSelect from '@/components/PhoneModelMultiSelect/index.vue'
import PartnerPhoto from '@/views/partner/PartnerPhoto.vue'
import {newRequestId} from '@/api/modules/partner'
import {getDocuments,uploadDocument,type AttachmentVO} from '@/api/modules/attachment'
import {useUserStore} from '@/stores/user'
import {MAX_UPLOAD_FILE_SIZE_BYTES,formatFileSize} from '@/utils/file'
import {previewSupplierColors,previewSupplierRange,saveSupplierColors,saveSupplierRanges,supplierColors,supplierRanges,updateSupplierShortCode,type SupplierColor,type SupplierColorReference,type SupplierRange,type SupplierRangeMember,type SupplierRangePreview,type SupplierScopeMetadata} from '@/api/modules/supplierRanges'
import {partnerError} from '@/utils/partnerError'
import {parseSelectionTsv} from '@/utils/partnerSelections'
const props=defineProps<{supplierCode:string;canWrite:boolean;initialTab?:'model'|'color'|'colors';initialColorText?:string}>()
const emit=defineEmits<{'metadata-saved':[supplierCode:string,metadata:SupplierScopeMetadata]}>()
const tab=ref<'model'|'color'|'colors'>(props.initialTab||'model'),keyword=ref(''),page=ref(1),total=ref(0),rows=ref<(SupplierRange|SupplierColor)[]>([]),meta=ref<SupplierScopeMetadata>(),shortCode=ref(''),error=ref(''),busy=ref(false),allowed=ref(false)
const dialog=ref(false),colorDialog=ref(false),colorText=ref(''),colorPreview=ref<Partial<SupplierColor>[]>([]),colorChecked=ref(false),colorPreviewResult=ref(''),reason=ref(''),raw=ref(''),preview=ref<SupplierRangePreview>(),phoneIds=ref<number[]>([]),colorIds=ref<number[]>([]),colorOptions=ref<SupplierColor[]>([]),colorPage=ref(1),colorTotal=ref(0),colorKeyword=ref('')
const colorEditor=ref<SupplierColor>()
const user=useUserStore(),imageTarget=ref<Partial<SupplierColor>>(),imageOptions=ref<AttachmentVO[]>([]),imageSelected=ref(new Map<number,SupplierColorReference>()),imageKeyword=ref(''),imagePage=ref(1),imageTotal=ref(0),imageBusy=ref(false),imageError=ref('')
let imageGeneration=0
const isColorImage=(ref:SupplierColorReference)=>String(ref.contentType||ref.type||'').startsWith('image/')||/\.(png|jpe?g|webp|gif)$/i.test(ref.name||'')
const imageReference=(file:AttachmentVO):SupplierColorReference=>({id:file.attachmentId,name:file.originalFileName,version:file.versionNo,type:file.contentType||'',contentType:file.contentType||'',size:file.fileSize})
const canUploadImage=computed(()=>canEdit.value&&user.hasPermission('documents:write'))
const form=reactive<Partial<SupplierRange>>({}),canEdit=computed(()=>props.canWrite&&allowed.value),rangeMode=computed(()=>tab.value!=='colors')
const stateName=(value:string)=>({active:'可用',draft:'待核实',inactive:'已停用'} as Record<string,string>)[value]||value
let sequence=0
async function load(){const seq=++sequence;busy.value=true;error.value='';try{const data=tab.value==='colors'?await supplierColors(props.supplierCode,{page:page.value,size:20,keyword:keyword.value}):await supplierRanges(props.supplierCode,{page:page.value,size:20,keyword:keyword.value,type:tab.value});if(seq!==sequence)return;rows.value=data.content;total.value=data.totalElements;meta.value=data.supplier;shortCode.value=data.supplier.shortCode||'';allowed.value=data.canWrite}catch(e){error.value=partnerError(e)}finally{if(seq===sequence)busy.value=false}}
watch(()=>[props.supplierCode,tab.value],()=>{page.value=1;void load()},{immediate:true})
watch(()=>props.supplierCode,()=>{imageGeneration++;imageTarget.value=undefined;colorEditor.value=undefined;imageOptions.value=[];imageSelected.value=new Map()})
async function loadColorImages(){const seq=++imageGeneration;imageBusy.value=true;imageError.value='';try{const data=await getDocuments({fileCategory:'sample_image',keyword:imageKeyword.value.trim(),page:imagePage.value,size:12,status:'all'});if(seq!==imageGeneration)return;imageOptions.value=data.content.map(row=>row.latestVersion).filter(file=>file.contentType?.startsWith('image/'));imageTotal.value=data.totalElements}catch(e){if(seq===imageGeneration)imageError.value=partnerError(e)}finally{if(seq===imageGeneration)imageBusy.value=false}}
function chooseColorImages(target:Partial<SupplierColor>){if(!canEdit.value)return;imageTarget.value=target;imageSelected.value=new Map((target.refs||[]).map(ref=>[ref.id,{...ref}]));imageKeyword.value='';imagePage.value=1;void loadColorImages()}
function toggleColorImage(file:AttachmentVO,value:boolean){const refs=new Map(imageSelected.value);if(value)refs.set(file.attachmentId,imageReference(file));else refs.delete(file.attachmentId);imageSelected.value=refs}
function applyColorImages(){if(imageTarget.value)imageTarget.value.refs=[...imageSelected.value.values()];imageGeneration++;imageTarget.value=undefined}
function closeColorImages(){imageGeneration++;imageTarget.value=undefined;imageOptions.value=[];imageBusy.value=false}
function removeColorImage(target:Partial<SupplierColor>,id:number){target.refs=(target.refs||[]).filter(ref=>ref.id!==id)}
async function uploadColorImage(file:File){if(!canUploadImage.value)return false;imageBusy.value=true;imageError.value='';try{if(!file.type.startsWith('image/'))throw new Error('原色依据只支持图片，请保留报价原件在原选品资料中。');if(file.size>MAX_UPLOAD_FILE_SIZE_BYTES)throw new Error(`单个文件不能超过 ${formatFileSize(MAX_UPLOAD_FILE_SIZE_BYTES)}`);const saved=await uploadDocument(file,{fileCategory:'sample_image',versionNo:'V1',references:[],remark:`供应商 ${props.supplierCode} 原色 ${imageTarget.value?.name||''} 的图片依据`});toggleColorImage(saved,true);imagePage.value=1;imageKeyword.value='';await loadColorImages()}catch(e){imageError.value=partnerError(e)}finally{imageBusy.value=false}return false}
async function saveCode(){if(!meta.value||!canEdit.value||busy.value)return;const code=props.supplierCode,value=shortCode.value.trim().toUpperCase(),unchanged=value===(meta.value.shortCode||'').trim().toUpperCase();error.value='';if(value&&!unchanged&&!/^[A-Z0-9][A-Z0-9-]*$/.test(value)){error.value='简码只用大写英文字母、数字和半角 -，不能含中文、空格或下划线。';return}busy.value=true;try{const saved=await updateSupplierShortCode(code,{version:meta.value.version,shortCode:value,reason:'国内工程维护供应商简码',requestId:newRequestId()});emit('metadata-saved',code,saved);if(props.supplierCode===code){meta.value=saved;shortCode.value=saved.shortCode||''}ElMessage.success('简码已保存；已有编号和历史标签不变')}catch(e){if(props.supplierCode===code)error.value=partnerError(e)}finally{if(props.supplierCode===code)busy.value=false}}
async function loadColors(){try{const data=await supplierColors(props.supplierCode,{page:colorPage.value,size:20,keyword:colorKeyword.value});colorOptions.value=data.content;colorTotal.value=data.totalElements}catch(e){error.value=partnerError(e)}}
function openRange(row?:SupplierRange){Object.keys(form).forEach(key=>delete (form as Record<string,unknown>)[key]);Object.assign(form,row?JSON.parse(JSON.stringify(row)):{id:0,version:0,type:tab.value==='color'?'color':'model',name:'',aliases:[],members:[],status:'draft',styleKey:'',configKey:'',notes:''});phoneIds.value=form.type==='model'?(form.members||[]).map(item=>item.id):[];colorIds.value=form.type==='color'?(form.members||[]).map(item=>item.id):[];raw.value=(form.pendingValues||[]).map(value=>typeof value==='string'?value:String((value as Record<string,unknown>).raw||'')).join('\n');reason.value='';preview.value=undefined;dialog.value=true;if(form.type==='color')void loadColors()}
function toggleColor(id:number,checked:boolean){colorIds.value=checked?[...new Set([...colorIds.value,id])]:colorIds.value.filter(value=>value!==id);preview.value=undefined}
async function checkRange(){busy.value=true;error.value='';try{preview.value=await previewSupplierRange(props.supplierCode,{type:form.type!,values:raw.value.split(/\r?\n|\t/).map(value=>value.trim()).filter(Boolean),memberIds:form.type==='model'?phoneIds.value:colorIds.value,styleKey:form.styleKey,configKey:form.configKey})}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function resolveMember(index:number,id:number){if(!preview.value)return;const row=preview.value.rows[index],member=row.candidates.find(item=>item.id===id);if(!member)return;row.member=member;row.state='matched';preview.value.members=[...new Map(preview.value.rows.filter(item=>item.member).map(item=>[item.member!.id,item.member!])).values(),...(form.type==='model'?phoneIds.value:colorIds.value).filter(value=>!preview.value!.rows.some(item=>item.member?.id===value)).map(value=>({id:value}))];preview.value.unresolvedCount=preview.value.rows.filter(item=>item.state==='missing'||item.state==='ambiguous').length}
async function saveRange(){if(!preview.value||!form.name?.trim()||!reason.value.trim())return;busy.value=true;error.value='';try{await saveSupplierRanges(props.supplierCode,{requestId:newRequestId(),reason:reason.value,items:[{...form,members:preview.value.members,pendingValues:preview.value.rows.filter(row=>row.state==='missing'||row.state==='ambiguous'),status:preview.value.unresolvedCount?'draft':form.status}]});dialog.value=false;ElMessage.success('范围新版本已保存；既有选品依据不变');await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function beginColors(){colorText.value=props.initialColorText||'';colorPreview.value=[];colorChecked.value=false;colorPreviewResult.value='';reason.value='';colorDialog.value=true}
async function checkColors(){busy.value=true;error.value='';try{const inputs:Partial<SupplierColor>[]=parseSelectionTsv(colorText.value).map(cells=>({id:0,version:0,name:cells[0].trim(),supplierColorCode:cells[1]?.trim()||'',styleKey:cells[2]?.trim()||'',configKey:cells[3]?.trim()||'',notes:cells[4]||'',refs:[],status:'active'}));if(inputs.some(item=>!item.name))throw new Error('每条原色至少填写名称。');const result=await previewSupplierColors(props.supplierCode,inputs);const saved:Partial<SupplierColor>[]=[];const messages:string[]=[];let unresolved=false;result.rows.forEach((row,index)=>{const state=String(row.state),candidates=(row.candidates||[]) as SupplierColor[];messages.push(`${inputs[index]?.name||row.name}：${({new:'拟新增',matched:'已有，复用不重复新增',duplicate:'本次重复，保留一次',ambiguous:'存在多条，请补色号／款式后再核对',missing:'缺少名称或依据'})[state]||state}`);if(state==='new')saved.push(inputs[index]);else if(state==='matched'&&candidates.length===1){/* Existing colors are referenced, not rewritten by an import. */}else if(state!=='duplicate')unresolved=true});colorPreview.value=saved;colorPreviewResult.value=messages.join('\n');colorChecked.value=!unresolved;if(unresolved)error.value='有重名待核对或缺资料项；请补充原文后重新核对，不会丢弃后直接保存。'}catch(e){colorChecked.value=false;error.value=partnerError(e)}finally{busy.value=false}}
async function saveColors(){if(!colorChecked.value||!reason.value.trim())return;busy.value=true;error.value='';try{await saveSupplierColors(props.supplierCode,{items:colorPreview.value,reason:reason.value,requestId:newRequestId()});colorDialog.value=false;await load();ElMessage.success('供应商原色已保存；未创建公司标准色码')}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function editColor(row:SupplierColor){colorEditor.value=JSON.parse(JSON.stringify(row));reason.value=''}
async function saveColor(){if(!colorEditor.value?.name?.trim()||!reason.value.trim())return;busy.value=true;try{await saveSupplierColors(props.supplierCode,{items:[colorEditor.value],reason:reason.value,requestId:newRequestId()});colorEditor.value=undefined;await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
async function readList(file:File,target:'range'|'color'){try{const text=await file.text(),cells=parseSelectionTsv(text.replace(/^\uFEFF/,''),file.name.toLowerCase().endsWith('.csv')?',':'\t');if(target==='range'){if(cells.some(row=>row.slice(1).some(value=>value.trim())))throw new Error('型号／颜色范围清单请只放一列名称或编码；多列资料请直接复制需要的一列。');raw.value=cells.map(row=>row[0]).join('\n');preview.value=undefined}else{colorText.value=cells.map(row=>row.map(value=>'"'+value.replace(/"/g,'""')+'"').join('\t')).join('\n');colorChecked.value=false}}catch(e){error.value=partnerError(e)}return false}
const readRangeList=(file:File)=>readList(file,'range'),readColorList=(file:File)=>readList(file,'color')
const memberName=(member:SupplierRangeMember)=>String(member.name||member.modelName||member.raw||member.code||`#${member.id}`)
</script>
<template><section class="supplier-ranges" v-loading="busy"><header><h3>型号与颜色范围</h3><span class="muted">范围按供应商独立维护；引用范围不等于全部组合可供</span></header>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <div class="range-toolbar"><label>供应商简码</label><el-input v-model="shortCode" :disabled="!canEdit" placeholder="如 XD、XDT、XD2" aria-label="供应商简码"/><el-button v-if="canEdit" :disabled="busy" @click="saveCode">保存简码</el-button></div>
 <p class="muted short-code-help">全系统唯一，熊大保留 XD；建议 2—4 位，不固定三位。可用大写英文、数字和半角 -，旧简码与历史标签保留追溯。</p>
 <div class="range-toolbar"><el-radio-group v-model="tab" size="small"><el-radio-button value="model">型号范围</el-radio-button><el-radio-button value="color">颜色范围</el-radio-button><el-radio-button value="colors">供应商原色</el-radio-button></el-radio-group><el-input v-model="keyword" clearable placeholder="名称／编码／别名" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">查询</el-button><el-button v-if="canEdit" type="primary" @click="rangeMode?openRange():beginColors()">{{rangeMode?'新增范围':'批量录入原色'}}</el-button></div>
 <div class="range-list"><article v-for="row in rows" :key="row.id"><div><strong>{{row.name}}</strong><p>{{row.code}} · {{stateName(row.status)}} · V{{row.version}}</p><p v-if="'members' in row">{{row.members.length}} 个明确成员 <span v-if="row.aliases.length">· 别名 {{row.aliases.join('、')}}</span></p><p v-else>原色号 {{row.supplierColorCode||'未提供'}} · {{row.styleKey||'不限款式'}} / {{row.configKey||'不限配置'}}</p></div><div class="range-preview"><template v-if="'members' in row"><span>{{row.members.slice(0,3).map(memberName).join('、')}}</span><details v-if="row.members.length>3"><summary>查看全部成员</summary>{{row.members.map(memberName).join('、')}}</details></template><template v-else><span>{{row.notes}}</span><p v-for="ref in row.refs" :key="ref.id" class="color-image-reference"><PartnerPhoto v-if="isColorImage(ref)" :id="ref.id"/>{{ref.name||'原色依据'}} · {{ref.version}}</p></template></div><el-button v-if="canEdit&&'members' in row" link type="primary" @click="openRange(row)">批量增补／移除</el-button><el-button v-else-if="canEdit" link type="primary" @click="editColor(row as SupplierColor)">维护原色</el-button></article><el-empty v-if="!rows.length&&!busy" description="暂无记录；可直接整列粘贴批量维护"/></div>
 <el-pagination v-model:current-page="page" :total="total" :page-size="20" :pager-count="5" layout="total,prev,pager,next" @current-change="load"/>
 <el-dialog v-model="dialog" :title="form.id?'维护范围新版本':'新增范围'" width="min(900px,96vw)" append-to-body :close-on-click-modal="false"><el-form label-position="top" size="small"><div class="range-fields"><el-form-item label="范围名称 *"><el-input v-model="form.name"/></el-form-item><el-form-item label="别名（用逗号分隔）"><el-input :model-value="form.aliases?.join('，')" @update:model-value="form.aliases=String($event).split(/[，,]/).map(v=>v.trim()).filter(Boolean)"/></el-form-item><el-form-item label="仅适用款式（可空）"><el-input v-model="form.styleKey"/></el-form-item><el-form-item label="仅适用配置（可空）"><el-input v-model="form.configKey"/></el-form-item></div>
 <el-form-item v-if="form.type==='model'" label="从现有手机资料批量选择"><PhoneModelMultiSelect v-model="phoneIds" @update:model-value="preview=undefined"/></el-form-item>
 <el-form-item v-else label="从本供应商原色批量选择"><div class="color-choices"><div class="range-toolbar"><el-input v-model="colorKeyword" placeholder="搜索本供应商原色" @keyup.enter="colorPage=1;loadColors()"/><el-button @click="colorPage=1;loadColors()">查询</el-button></div><el-checkbox v-for="color in colorOptions" :key="color.id" :model-value="colorIds.includes(color.id)" @change="toggleColor(color.id,Boolean($event))">{{color.name}} · {{color.supplierColorCode||color.code}}</el-checkbox><el-pagination v-model:current-page="colorPage" :total="colorTotal" :page-size="20" layout="prev,pager,next" @current-change="loadColors"/><p>已选 {{colorIds.length}} 项，跨页保留。</p></div></el-form-item>
 <el-form-item label="或粘贴一列名称／已有编码（不自动新增手机及标准颜色）"><el-input v-model="raw" type="textarea" :rows="4" @input="preview=undefined"/><el-upload :show-file-list="false" accept=".csv,.tsv,.txt" :before-upload="readRangeList"><el-button link>导入文本清单（Excel也可整列复制粘贴）</el-button></el-upload></el-form-item>
 <el-button :disabled="busy" @click="checkRange">核对成员与变更差异</el-button><section v-if="preview" class="range-diff"><p>拟保存 {{preview.members.length}} 个明确成员 · {{preview.unresolvedCount}} 项待核实；未核实只能存草稿。</p><p v-if="form.id">较旧版新增 {{preview.members.filter(m=>!form.members?.some(o=>o.id===m.id)).length}} 项，移除 {{form.members?.filter(m=>!preview?.members.some(n=>n.id===m.id)).length}} 项。移除只影响新版本，不改变历史依据。</p><article v-for="(item,index) in preview.rows" :key="index"><span>{{item.raw}} · {{({matched:'已匹配',duplicate:'重复',ambiguous:'多义待选',missing:'未找到'})[item.state]}}</span><el-select v-if="item.state==='ambiguous'" placeholder="明确选择已有成员" @update:model-value="resolveMember(index,Number($event))"><el-option v-for="candidate in item.candidates" :key="candidate.id" :value="candidate.id" :label="memberName(candidate)"/></el-select></article></section>
 <el-form-item label="状态"><el-select v-model="form.status"><el-option label="待核实草稿" value="draft"/><el-option label="可用（成员全部核实）" value="active"/><el-option label="停用（保留历史）" value="inactive"/></el-select></el-form-item><el-form-item label="本次维护原因 *"><el-input v-model="reason" type="textarea" autosize/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :disabled="!preview||!form.name?.trim()||!reason.trim()||busy" @click="saveRange">保存新版本</el-button></template></el-dialog>
 <el-dialog v-model="colorDialog" title="批量维护供应商原色" width="min(850px,96vw)" append-to-body :close-on-click-modal="false"><p>每行：颜色原名、供方色号、适用款式、适用配置、备注（后四列可空）。粘贴Excel矩形区域；同名但色卡／配置不同须保留差异。</p><el-input v-model="colorText" type="textarea" :rows="8" @input="colorChecked=false"/><el-upload :show-file-list="false" accept=".csv,.tsv,.txt" :before-upload="readColorList"><el-button link>导入文本清单</el-button></el-upload><el-button @click="checkColors">核对新增与已有原色</el-button><pre v-if="colorChecked" class="range-diff">{{colorPreviewResult}}</pre><section v-if="colorChecked&&colorPreview.length" class="bulk-color-images"><article v-for="(item,index) in colorPreview" :key="index"><strong>{{item.name}}</strong><el-button link type="primary" @click="chooseColorImages(item)">选择已有授权图片</el-button><div v-for="ref in item.refs||[]" :key="ref.id" class="color-image-reference"><PartnerPhoto v-if="isColorImage(ref)" :id="ref.id"/><span>{{ref.name||'原色图片'}} · {{ref.version}}</span><el-button link @click="removeColorImage(item,ref.id)">移除引用</el-button></div></article></section><el-form-item label="本次维护原因 *"><el-input v-model="reason"/></el-form-item><template #footer><el-button @click="colorDialog=false">取消</el-button><el-button type="primary" :disabled="!colorChecked||!reason.trim()||busy" @click="saveColors">确认批量保存</el-button></template></el-dialog>
 <el-dialog :model-value="!!colorEditor" title="维护供应商原色（不改公司标准颜色）" width="min(650px,96vw)" append-to-body @update:model-value="!$event&&(colorEditor=undefined)"><el-form v-if="colorEditor" label-position="top"><el-form-item label="供应商颜色原名 *"><el-input v-model="colorEditor.name"/></el-form-item><el-form-item label="供方色号"><el-input v-model="colorEditor.supplierColorCode"/></el-form-item><el-form-item label="仅适用款式／配置"><div class="range-toolbar"><el-input v-model="colorEditor.styleKey" placeholder="款式（可空）"/><el-input v-model="colorEditor.configKey" placeholder="配置（可空）"/></div></el-form-item><el-form-item label="状态"><el-select v-model="colorEditor.status"><el-option label="可用" value="active"/><el-option label="停用（保留历史）" value="inactive"/></el-select></el-form-item><section class="color-image-section"><header><h3>原色图片依据</h3><el-button type="primary" link @click="chooseColorImages(colorEditor)">选择已有授权图片</el-button></header><p class="muted">引用已有照片，不重复复制文件；移除仅取消该原色引用，不删除原文件。</p><div v-for="ref in colorEditor.refs" :key="ref.id" class="color-image-reference"><PartnerPhoto v-if="isColorImage(ref)" :id="ref.id"/><span>{{ref.name||'原色图片'}} · {{ref.version}}</span><el-button link @click="removeColorImage(colorEditor,ref.id)">移除引用</el-button></div><p v-if="!colorEditor.refs.length" class="muted">暂无原色图片，可从已上传的选品／样品照片中选择。</p></section><el-form-item label="备注"><el-input v-model="colorEditor.notes" type="textarea" autosize/></el-form-item><el-form-item label="本次维护原因 *"><el-input v-model="reason" type="textarea" autosize/></el-form-item></el-form><template #footer><el-button @click="colorEditor=undefined">取消</el-button><el-button type="primary" :disabled="!colorEditor?.name?.trim()||!reason.trim()||busy" @click="saveColor">保存原色新版本</el-button></template></el-dialog>
 <el-dialog :model-value="!!imageTarget" title="选择已有授权图片（只引用，不复制）" width="min(850px,96vw)" append-to-body @update:model-value="!$event&&closeColorImages()"><section v-loading="imageBusy" class="color-image-picker"><p>复用文件中心的示例照片，只展示当前账号可读的图片；请核对图片确实对应本供应商和本原色。</p><el-alert v-if="imageError" :title="imageError" type="error" :closable="false"/><div class="range-toolbar"><el-input v-model="imageKeyword" clearable placeholder="搜索已有图片名称" aria-label="搜索原色图片" @keyup.enter="imagePage=1;loadColorImages()"/><el-button :disabled="imageBusy" @click="imagePage=1;loadColorImages()">查找图片</el-button><el-upload v-if="canUploadImage" :show-file-list="false" :before-upload="uploadColorImage" :disabled="imageBusy" accept=".png,.jpg,.jpeg,.webp"><el-button :disabled="imageBusy">上传新图片</el-button></el-upload></div><div class="color-image-options"><article v-for="file in imageOptions" :key="file.attachmentId"><PartnerPhoto :id="file.attachmentId"/><el-checkbox :model-value="imageSelected.has(file.attachmentId)" :aria-label="`采用原色图片${file.originalFileName}`" @change="toggleColorImage(file,Boolean($event))">{{file.originalFileName}} · {{file.versionNo}}</el-checkbox></article></div><el-empty v-if="!imageOptions.length&&!imageBusy" description="当前页没有可读图片；可按原选品图片文件名搜索"/><el-pagination v-model:current-page="imagePage" :total="imageTotal" :page-size="12" :pager-count="5" layout="total,prev,pager,next" @current-change="loadColorImages"/><p>已选 {{imageSelected.size}} 张；跨页选择保留，取消不改变原色记录。</p></section><template #footer><el-button :disabled="imageBusy" @click="closeColorImages">取消</el-button><el-button type="primary" :disabled="imageBusy" @click="applyColorImages">采用所选图片（待保存原色）</el-button></template></el-dialog>
</section></template>
<style scoped>.color-image-reference{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:12px;overflow-wrap:anywhere;margin:6px 0}.color-image-reference>span{min-width:0;flex:1}.color-image-section{margin:8px 0}.bulk-color-images article{padding:6px 0;border-bottom:1px solid #e7edf5}.bulk-color-images article>strong{margin-right:12px}.color-image-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.color-image-options article{display:flex;align-items:center;gap:8px;min-width:0;padding:7px;border:1px solid #e4ebf3;border-radius:6px}.color-image-options :deep(.el-checkbox){height:auto;min-width:0;margin-right:0}.color-image-options :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere;min-width:0;font-size:12px}.color-image-picker{container-type:inline-size}.color-image-picker p{font-size:12px;line-height:1.6}.color-image-picker :deep(.el-pagination){flex-wrap:wrap;margin-top:7px}@container(max-width:500px){.color-image-options{grid-template-columns:minmax(0,1fr)}}</style>
<style scoped>.supplier-ranges{min-width:0;container-type:inline-size}.supplier-ranges header,.range-toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}.supplier-ranges h3{margin:0;font-size:14px}.muted,.range-list p{font-size:12px;color:#6c7d92}.range-toolbar>.el-input{flex:1;min-width:130px}.range-toolbar>label{font-size:12px}.range-list article{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr) auto;gap:12px;align-items:center;padding:8px 0;border-bottom:1px solid #e7edf5}.range-list article>*{min-width:0;overflow-wrap:anywhere}.range-list p{margin:3px 0;line-height:1.6}.range-preview{font-size:12px;line-height:1.7}.range-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.range-diff{max-height:240px;overflow:auto;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0;padding:8px;background:#f6f8fb}.range-diff article{display:flex;gap:8px;padding:4px 0;align-items:center}.color-choices{width:100%;min-width:0}.color-choices .el-checkbox{height:auto;min-height:28px}.supplier-ranges :deep(.el-pagination){flex-wrap:wrap;margin-top:7px}.supplier-ranges :deep(.el-button){white-space:normal;height:auto;line-height:1.6;min-height:26px}.supplier-ranges :deep(.el-button+.el-button){margin-left:0}@container(max-width:650px){.range-list article{grid-template-columns:minmax(0,1fr) auto}.range-preview{grid-column:1/-1}.range-list article>.el-button{grid-column:2;grid-row:1}.range-fields{grid-template-columns:1fr}}</style>
